  "common.required": "\u0b0f\u0b39\u0b3f \u0b15\u0b4d\u0b37\u0b47\u0b24\u0b4d\u0b30 \u0b06\u0b2c\u0b36\u0b4d\u0b5f\u0b15",
  "common.viewProfile": "\u0b2a\u0b4d\u0b30\u0b4b\u0b2b\u0b3e\u0b07\u0b32\u0b4d \u0b26\u0b47\u0b16\u0b28\u0b4d\u0b24\u0b41",
  "landing.hero.badge": "100% \u0b2e\u0b3e\u0b17\u0b23\u0b3e \u0b0f\u0b2c\u0b02 \u0b2c\u0b4d\u0b5f\u0b15\u0b4d\u0b24\u0b3f\u0b17\u0b24",
  "landing.hero.h1": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f \u0b2a\u0b3e\u0b07\u0b01 \u0b38\u0b20\u0b3f\u0b15\u0b4d \u0b38\u0b30\u0b15\u0b3e\u0b30\u0b40 \u0b2f\u0b4b\u0b1c\u0b28\u0b3e \u0b16\u0b4b\u0b1c\u0b28\u0b4d\u0b24\u0b41",
  "landing.hero.h1.accent": "\u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f",
  "landing.hero.sub": "VittVaani \u0b2d\u0b3e\u0b30\u0b24\u0b30 \u0b15\u0b47\u0b28\u0b4d\u0b26\u0b4d\u0b30 \u0b0f\u0b2c\u0b02 \u0b30\u0b3e\u0b1c\u0b4d\u0b5f \u0b38\u0b30\u0b15\u0b3e\u0b30\u0b19\u0b4d\u0b15 \u0b2f\u0b4b\u0b1c\u0b28\u0b3e\u0b15\u0b41 \u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b2a\u0b4d\u0b30\u0b4b\u0b2b\u0b3e\u0b07\u0b32\u0b4d \u0b38\u0b39\u0b3f\u0b24 \u0b2e\u0b47\u0b33\u0b3e\u0b0f \u2014 \u0b38\u0b30\u0b33 \u0b13\u0b21\u0b3c\u0b3f\u0b06, \u0b2a\u0b26\u0b15\u0b4d\u0b37\u0b47\u0b2a \u0b2a\u0b30\u0b47 \u0b2a\u0b26\u0b15\u0b4d\u0b37\u0b47\u0b2a\u0964",
  "landing.hero.cta": "\u0b2e\u0b47\u0b33\u0b3e\u0b07\u0b2c\u0b3e \u0b06\u0b30\u0b2e\u0b4d\u0b2d \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "landing.hero.cta2": "\u0b0f\u0b39\u0b3e \u0b15\u0b3f\u0b2a\u0b30\u0b3f \u0b15\u0b3e\u0b2e \u0b15\u0b30\u0b47",
  "landing.how.title": "\u0b0f\u0b39\u0b3e \u0b15\u0b3f\u0b2a\u0b30\u0b3f \u0b15\u0b3e\u0b2e \u0b15\u0b30\u0b47",
  "landing.how.1.title": "\u0b28\u0b3f\u0b1c \u0b2c\u0b3f\u0b37\u0b5f\u0b30\u0b47 \u0b15\u0b41\u0b39\u0b28\u0b4d\u0b24\u0b41",
  "landing.how.1.text": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f, \u0b38\u0b4d\u0b25\u0b3e\u0b28 \u0b0f\u0b2c\u0b02 \u0b2a\u0b43\u0b37\u0b4d\u0b20\u0b2d\u0b42\u0b2e\u0b3f \u0b2c\u0b3f\u0b37\u0b5f\u0b30\u0b47 9 \u0b38\u0b30\u0b33 \u0b2a\u0b4d\u0b30\u0b36\u0b4d\u0b28\u0b30 \u0b09\u0b24\u0b4d\u0b24\u0b30 \u0b26\u0b3f\u0b05\u0b28\u0b4d\u0b24\u0b41\u0964",
  "landing.how.2.title": "\u0b06\u0b2e\u0b47 \u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15\u0b41 \u0b2e\u0b47\u0b33\u0b3e\u0b07\u0b2c\u0b3e",
  "landing.how.2.text": "\u0b06\u0b2e\u0b30 \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b4d\u0b25\u0b3e \u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b09\u0b24\u0b4d\u0b24\u0b30\u0b30\u0b41 14 \u0b15\u0b4d\u0b37\u0b47\u0b24\u0b4d\u0b30\u0b30\u0b47 90+ \u0b2f\u0b4b\u0b1c\u0b28\u0b3e\u0b15\u0b41 \u0b15\u0b4d\u0b30\u0b2e\u0b3e\u0b19\u0b4d\u0b15\u0b3f\u0b24 \u0b15\u0b30\u0b47\u0964",
  "landing.how.3.title": "\u0b2c\u0b4d\u0b5f\u0b3e\u0b16\u0b4d\u0b5f\u0b3e \u0b2a\u0b3e\u0b06\u0b28\u0b4d\u0b24\u0b41",
  "landing.how.3.text": "\u0b2a\u0b4d\u0b30\u0b24\u0b4d\u0b5f\u0b47\u0b15 \u0b2f\u0b4b\u0b1c\u0b28\u0b3e \u0b15\u0b3e\u0b39\u0b3f\u0b01\u0b15\u0b3f \u0b09\u0b2a\u0b2f\u0b41\u0b15\u0b4d\u0b24 \u0b24\u0b3e\u0b39\u0b3e\u0b30 \u0b38\u0b4d\u0b2a\u0b37\u0b4d\u0b1f \u0b15\u0b3e\u0b30\u0b23 \u2014 \u0b15\u0b20\u0b3f\u0b28 \u0b36\u0b2c\u0b4d\u0b26 \u0b2c\u0b3f\u0b28\u0b3e\u0964",
  "landing.how.4.title": "\u0b06\u0b24\u0b4d\u0b2e\u0b2c\u0b3f\u0b36\u0b4d\u0b71\u0b3e\u0b38\u0b30\u0b47 \u0b06\u0b2c\u0b47\u0b26\u0b28 \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "landing.how.4.text": "\u0b26\u0b32\u0b3f\u0b32, \u0b24\u0b3e\u0b30\u0b3f\u0b16 \u0b0f\u0b2c\u0b02 \u0b38\u0b3e\u0b2a\u0b4d\u0b24\u0b3e\u0b39\u0b3f\u0b15 \u0b06\u0b2c\u0b47\u0b26\u0b28 \u0b30\u0b4b\u0b21\u0b2e\u0b4d\u0b5f\u0b3e\u0b2a\u0b4d \u0b2a\u0b3e\u0b06\u0b28\u0b4d\u0b24\u0b41\u0964",
  "landing.stats.title": "\u0b06\u0b17\u0b15\u0b41 \u0b06\u0b38\u0b41\u0b25\u0b3f\u0b2c\u0b3e \u0b09\u0b26\u0b4d\u0b5f\u0b4b\u0b17\u0b40\u0b19\u0b4d\u0b15 \u0b2c\u0b3f\u0b36\u0b4d\u0b71\u0b3e\u0b38",
  "landing.stats.schemes": "\u0b05\u0b28\u0b4d\u0b24\u0b30\u0b4d\u0b2d\u0b41\u0b15\u0b4d\u0b24 \u0b2f\u0b4b\u0b1c\u0b28\u0b3e",
  "landing.stats.sectors": "\u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f \u0b15\u0b4d\u0b37\u0b47\u0b24\u0b4d\u0b30",
  "landing.stats.states": "\u0b05\u0b28\u0b4d\u0b24\u0b30\u0b4d\u0b2d\u0b41\u0b15\u0b4d\u0b24 \u0b30\u0b3e\u0b1c\u0b4d\u0b5f",
  "landing.stats.languages": "\u0b2d\u0b3e\u0b37\u0b3e",
  "landing.features.title": "\u0b2a\u0b4d\u0b30\u0b15\u0b43\u0b24 \u0b09\u0b26\u0b4d\u0b5f\u0b4b\u0b17\u0b40\u0b19\u0b4d\u0b15 \u0b2a\u0b3e\u0b07\u0b01 \u0b24\u0b3f\u0b06\u0b30\u0b3f",
  "landing.features.1.title": "\u0b2a\u0b4d\u0b30\u0b25\u0b2e\u0b47 \u0b38\u0b4d\u0b71\u0b30 + \u0b2a\u0b3e\u0b20",
  "landing.features.1.text": "\u0b2f\u0b47\u0b15\u0b4c\u0b23\u0b38\u0b3f \u0b2b\u0b4b\u0b28\u0b30\u0b47, \u0b15\u0b2e\u0b4d \u0b21\u0b3e\u0b1f\u0b3e\u0b30\u0b47 \u0b39\u0b3e\u0b32\u0b41\u0b15\u0b3e \u0b1a\u0b33\u0b41\u0b25\u0b3f\u0b2c\u0b3e \u0b21\u0b3f\u0b1c\u0b3e\u0b07\u0b28\u0b4d\u0964",
  "landing.features.2.title": "23 \u0b2d\u0b3e\u0b37\u0b3e",
  "landing.features.2.text": "\u0b09\u0b2a\u0b30 \u0b2e\u0b47\u0b28\u0b41\u0b30\u0b41 \u0b2f\u0b47\u0b15\u0b4c\u0b23\u0b38\u0b3f \u0b2d\u0b3e\u0b30\u0b24\u0b40\u0b5f \u0b2d\u0b3e\u0b37\u0b3e \u0b2c\u0b3e\u0b1b\u0b28\u0b4d\u0b24\u0b41\u0964",
  "landing.features.3.title": "\u0b05\u0b2b\u0b4d\u0b32\u0b3e\u0b07\u0b28\u0b4d-\u0b05\u0b28\u0b41\u0b15\u0b42\u0b33",
  "landing.features.3.text": "\u0b2f\u0b4b\u0b1c\u0b28\u0b3e \u0b32\u0b4b\u0b15\u0b3e\u0b32\u0b4d \u0b15\u0b4d\u0b5f\u0b3e\u0b36\u0b30\u0b47 \u0b30\u0b39\u0b47 \u2014 \u0b07\u0b23\u0b4d\u0b1f\u0b30\u0b28\u0b47\u0b1f\u0b4d \u0b2c\u0b3f\u0b28\u0b3e \u0b2e\u0b27\u0b4d\u0b5f \u0b26\u0b47\u0b16\u0b3f \u0b39\u0b47\u0b2c\u0964",
  "landing.features.4.title": "\u0b17\u0b4b\u0b2a\u0b28\u0b40\u0b5f\u0b24\u0b3e\u0b15\u0b41 \u0b2a\u0b4d\u0b30\u0b3e\u0b25\u0b2e\u0b3f\u0b15\u0b24\u0b3e",
  "landing.features.4.text": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b21\u0b3e\u0b1f\u0b3e \u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15\u0b30 \u0b39\u0b3f\u0b01 \u0b30\u0b39\u0b47\u0964 \u0b15\u0b47\u0b2c\u0b47 \u0b2c\u0b3f\u0b15\u0b4d\u0b30\u0b3f \u0b39\u0b41\u0b0f \u0b28\u0b3e\u0b39\u0b3f\u0b01\u0964",
  "landing.cta.title": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b2f\u0b4b\u0b1c\u0b28\u0b3e \u0b16\u0b4b\u0b1c\u0b3f\u0b2c\u0b3e\u0b15\u0b41 \u0b2a\u0b4d\u0b30\u0b38\u0b4d\u0b24\u0b41\u0b24?",
  "landing.cta.text": "\u0b0f\u0b25\u0b3f\u0b30\u0b47 5 \u0b2e\u0b3f\u0b28\u0b3f\u0b1f\u0b4d \u0b30\u0b41 \u0b15\u0b2e\u0b4d \u0b38\u0b2e\u0b5f \u0b32\u0b3e\u0b17\u0b47\u0964",
  "auth.login.title": "\u0b38\u0b4d\u0b71\u0b3e\u0b17\u0b24",
  "auth.login.sub": "\u0b2e\u0b47\u0b33\u0b3e\u0b07\u0b2c\u0b3e \u0b2f\u0b3e\u0b24\u0b4d\u0b30\u0b3e \u0b1c\u0b3e\u0b30\u0b3f \u0b30\u0b16\u0b3f\u0b2c\u0b3e\u0b15\u0b41 \u0b32\u0b17\u0b4d \u0b07\u0b28\u0b4d \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "auth.register.title": "\u0b06\u0b15\u0b3e\u0b09\u0b23\u0b4d\u0b1f\u0b4d \u0b24\u0b3f\u0b06\u0b30\u0b3f \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "auth.register.sub": "\u0b38\u0b2c\u0b41\u0b2c\u0b47\u0b33\u0b47 \u0b2e\u0b3e\u0b17\u0b23\u0b3e\u0964 \u0b38\u0b47\u0b15\u0b47\u0b23\u0b4d\u0b21\u0b30\u0b47 \u0b2a\u0b1e\u0b4d\u0b1c\u0b40\u0b15\u0b30\u0b23 \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41\u0964",
  "auth.email": "\u0b07\u0b2e\u0b47\u0b32\u0b4d \u0b20\u0b3f\u0b15\u0b23\u0b3e",
  "auth.password": "\u0b2a\u0b3e\u0b38\u0b4d\u0b71\u0b3e\u0b30\u0b4d\u0b21",
  "auth.confirm": "\u0b2a\u0b3e\u0b38\u0b4d\u0b71\u0b3e\u0b30\u0b4d\u0b21 \u0b28\u0b3f\u0b36\u0b4d\u0b1a\u0b3f\u0b24 \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "auth.username": "\u0b28\u0b3e\u0b2e",
  "auth.phone": "\u0b2e\u0b4b\u0b2c\u0b3e\u0b07\u0b32\u0b4d \u0b28\u0b2e\u0b4d\u0b2c\u0b30",
