  "questionnaire.understand.explain": "\u0b2e\u0b41\u0b01 \u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f\u0b15\u0b41 \u0b0f\u0b2a\u0b30\u0b3f \u0b2c\u0b41\u0b1d\u0b3f\u0b32\u0b3f:",
