  "questionnaire.startLabel": "\u0b06\u0b30\u0b2e\u0b4d\u0b2d \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "questionnaire.gate.title": "\u0b06\u0b2a\u0b23 \u0b15\u0b3f\u0b2a\u0b30\u0b3f \u0b06\u0b30\u0b2e\u0b4d\u0b2d \u0b15\u0b30\u0b3f\u0b2c\u0b3e\u0b15\u0b41 \u0b1a\u0b3e\u0b39\u0b3e\u0b01\u0b28\u0b4d\u0b24\u0b3f?",
  "questionnaire.gate.sub": "\u0b09\u0b2d\u0b5f \u0b2a\u0b26\u0b4d\u0b27\u0b24\u0b3f\u0b30\u0b47 \u0b15\u0b3f\u0b1b\u0b3f \u0b2e\u0b3f\u0b28\u0b3f\u0b1f\u0b4d \u0b32\u0b3e\u0b17\u0b47\u0964 \u0b2f\u0b3e\u0b39\u0b3e \u0b38\u0b39\u0b1c \u0b32\u0b3e\u0b17\u0b47 \u0b2c\u0b3e\u0b1b\u0b28\u0b4d\u0b24\u0b41\u0964",
  "questionnaire.gate.describeTitle": "\u0b2e\u0b41\u0b01 \u0b2e\u0b4b \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f \u0b2c\u0b30\u0b4d\u0b23\u0b4d\u0b23\u0b28\u0b3e \u0b15\u0b30\u0b3f\u0b2c\u0b3f",
  "questionnaire.gate.describeSub": "\u0b28\u0b3f\u0b1c \u0b2d\u0b3e\u0b37\u0b3e\u0b30\u0b47 \u0b28\u0b3f\u0b1c \u0b15\u0b3e\u0b2e \u0b2c\u0b3f\u0b37\u0b5f\u0b30\u0b47 \u0b15\u0b41\u0b39\u0b28\u0b4d\u0b24\u0b41 \u0b15\u0b3f\u0b2e\u0b4d\u0b2c\u0b3e \u0b32\u0b47\u0b16\u0b28\u0b4d\u0b24\u0b41\u0964 \u0b2c\u0b3e\u0b15\u0b3f \u0b38\u0b2c\u0b41 \u0b06\u0b2e\u0b47 \u0b2d\u0b30\u0b3f\u0b26\u0b47\u0b09\u0964",
  "questionnaire.gate.formTitle": "\u0b2a\u0b26\u0b15\u0b4d\u0b37\u0b47\u0b2a \u0b05\u0b28\u0b41\u0b38\u0b3e\u0b30\u0b47 \u0b2b\u0b30\u0b4d\u0b2e \u0b2d\u0b30\u0b28\u0b4d\u0b24\u0b41",
  "questionnaire.gate.formSub": "\u0b1b\u0b4b\u0b1f, \u0b2e\u0b3e\u0b30\u0b4d\u0b17\u0b26\u0b30\u0b4d\u0b36\u0b15 \u0b2a\u0b4d\u0b30\u0b36\u0b4d\u0b28 \u2014 \u0b17\u0b4b\u0b1f\u0b3f\u0b0f \u0b38\u0b2e\u0b5f\u0b30\u0b47 \u0b17\u0b4b\u0b1f\u0b3f\u0b0f \u0b38\u0b30\u0b33 \u0b2a\u0b4d\u0b30\u0b36\u0b4d\u0b28\u0964",
  "questionnaire.gate.noProfileNote": "\u0b05\u0b32\u0b17\u0b3e \u0b2a\u0b4d\u0b30\u0b4b\u0b2b\u0b3e\u0b07\u0b32\u0b4d \u0b2b\u0b30\u0b4d\u0b2e \u0b26\u0b30\u0b15\u0b3e\u0b30 \u0b28\u0b3e\u0b39\u0b3f\u0b01 \u2014 \u0b2c\u0b30\u0b4d\u0b23\u0b4d\u0b23\u0b28\u0b3e \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41, \u0b06\u0b2e\u0b47 \u0b24\u0b3f\u0b06\u0b30\u0b3f \u0b15\u0b30\u0b3f\u0b26\u0b47\u0b2c\u0b41\u0964",
  "questionnaire.describe.title": "\u0b28\u0b3f\u0b1c \u0b2d\u0b3e\u0b37\u0b3e\u0b30\u0b47 \u0b28\u0b3f\u0b1c \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f \u0b2c\u0b3f\u0b37\u0b5f\u0b30\u0b47 \u0b15\u0b41\u0b39\u0b28\u0b4d\u0b24\u0b41",
  "questionnaire.describe.help": "\u0b15\u0b41\u0b39\u0b28\u0b4d\u0b24\u0b41 \u0b06\u0b2a\u0b23 \u0b15'\u0b23 \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b3f, \u0b24\u0b3e\u0b39\u0b3e \u0b1a\u0b3e\u0b32\u0b3f\u0b1b\u0b3f \u0b15\u0b3f \u0b06\u0b30\u0b2e\u0b4d\u0b2d \u0b39\u0b47\u0b09\u0b1b\u0b3f, \u0b0f\u0b2c\u0b02 \u0b15\u0b47\u0b09\u0b01 \u0b38\u0b3e\u0b39\u0b3e\u0b2f\u0b4d\u0b5f \u0b26\u0b30\u0b15\u0b3e\u0b30 (\u0b0b\u0b23, \u0b2a\u0b4d\u0b30\u0b36\u0b3f\u0b15\u0b4d\u0b37\u0b23, \u0b2c\u0b3f\u0b15\u0b4d\u0b30\u0b3f \u0b38\u0b3e\u0b39\u0b3e\u0b2f\u0b4d\u0b5f \u0b07\u0b24\u0b4d\u0b5f\u0b3e\u0b26\u0b3f)\u0964 \u0b06\u0b2a\u0b23 \u0b15\u0b25\u0b3e \u0b15\u0b39\u0b3f \u0b2e\u0b27\u0b4d\u0b5f \u0b15\u0b39\u0b3f\u0b2a\u0b3e\u0b30\u0b3f\u0b2c\u0b47\u0964",
  "questionnaire.describe.mic": "\u0b15\u0b41\u0b39\u0b28\u0b4d\u0b24\u0b41",
  "questionnaire.describe.micHint": "\u0b15\u0b25\u0b3e \u0b15\u0b39\u0b3f\u0b2c\u0b3e\u0b15\u0b41 \u0b2d\u0b32 \u0b32\u0b3e\u0b17\u0b47? \u0b2c\u0b1f\u0b28\u0b4d \u0b26\u0b2c\u0b3e\u0b07 \u0b15\u0b41\u0b39\u0b28\u0b4d\u0b24\u0b41:",
  "questionnaire.describe.micListening": "\u0b36\u0b41\u0b23\u0b41\u0b1b\u0b3f\u2026 \u0b38\u0b30\u0b3f\u0b32\u0b47 \u0b37\u0b4d\u0b1f\u0b2a\u0b4d \u0b26\u0b2c\u0b3e\u0b28\u0b4d\u0b24\u0b41",
  "questionnaire.describe.analyze": "\u0b2e\u0b4b \u0b2c\u0b4d\u0b5f\u0b2c\u0b38\u0b3e\u0b5f \u0b2c\u0b41\u0b1d\u0b28\u0b4d\u0b24\u0b41",
  "questionnaire.describe.thinking": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b15\u0b25\u0b3e \u0b2a\u0b22\u0b3f \u0b2c\u0b41\u0b1d\u0b41\u0b1b\u0b3f\u2026",
  "questionnaire.describe.failed": "\u0b15\u0b4d\u0b37\u0b2e\u0b3e \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41, \u0b0f\u0b25\u0b30 \u0b2c\u0b41\u0b1d\u0b3f\u0b2a\u0b3e\u0b30\u0b3f\u0b32\u0b3f \u0b28\u0b3e\u0b39\u0b3f\u0b01\u0964 \u0b26\u0b5f\u0b3e\u0b15\u0b30\u0b3f \u0b2a\u0b41\u0b23\u0b3f \u0b1a\u0b47\u0b37\u0b4d\u0b1f\u0b3e \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41\u0964",
  "questionnaire.describe.summaryTitle": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b2c\u0b3f\u0b37\u0b5f\u0b30\u0b47 \u0b2e\u0b41\u0b01 \u0b2f\u0b3e\u0b39\u0b3e \u0b2c\u0b41\u0b1d\u0b3f\u0b32\u0b3f",
  "questionnaire.describe.edit": "\u0b2e\u0b4b \u0b15\u0b25\u0b3e \u0b2c\u0b26\u0b33\u0b3e\u0b28\u0b4d\u0b24\u0b41",
