  "partners.guide.psb": "\u0b15\u0b2e \u0b38\u0b41\u0b27\u0b30\u0b47 \u0b2e\u0b3f\u0b06\u0b26\u0b3f \u0b13 \u0b36\u0b3f\u0b15\u0b4d\u0b37\u0b3e \u0b0b\u0b23\u0b30\u0b47 \u0b2c\u0b21\u0b3c \u0b38\u0b30\u0b15\u0b3e\u0b30\u0b40 \u0b2c\u0b4d\u0b5f\u0b3e\u0b19\u0b4d\u0b15\u0964",
  "partners.guide.rrb": "\u0b17\u0b3e\u0b01 \u0b28\u0b3f\u0b15\u0b1f \u0b2c\u0b4d\u0b5f\u0b3e\u0b19\u0b4d\u0b15; \u0b1a\u0b3e\u0b37 \u0b13 \u0b15\u0b4d\u0b37\u0b41\u0b26\u0b4d\u0b30 \u0b09\u0b26\u0b4d\u0b5f\u0b4b\u0b17\u0b30\u0b47 \u0b36\u0b4d\u0b30\u0b47\u0b37\u0b4d\u0b20\u0964",
  "partners.guide.nbfc": "\u0b2c\u0b28\u0b4d\u0b27\u0b3e \u0b2c\u0b3f\u0b28\u0b3e \u0b21\u0b4b\u0b30\u0b37\u0b4d\u0b1f\u0b47\u0b2a \u0b1b\u0b4b\u0b1f \u0b0b\u0b23; \u0b36\u0b40\u0b18\u0b4d\u0b30, \u0b1f\u0b3f\u0b15\u0b47 \u0b05\u0b27\u0b3f\u0b15 \u0b38\u0b41\u0b27\u0964",
